#!/usr/bin/env python3
"""
build-tracked-docx.py

Deterministic tracked-changes/comments builder for the proofread pipeline
(src/skills/proofread/SKILL.md, Phase 1.3 in
~/.claude/plans/the-plugin-did-terrable-swift-lantern.md). Takes the
ORIGINAL `.docx`, the final corrected text, an attribution map (the `stage`
field already carried on every change in changes-schema.json), and the
comment-worthy findings, and produces a `.proofed.docx` carrying real Word
tracked changes (`w:ins`/`w:del`) and real Word comments
(`word/comments.xml`).

Recorded findings this script exists to honour (Phase 0 RESULT / Research
digest Q3, verbatim from the plan of record):

  (a) python-docx's high-level object model silently ignores tracked
      changes on read and CORRUPTS existing revisions on save (GitHub
      issue #340, open since 2016; PR #1534 unmerged). All revision work
      here is direct lxml on the unzipped `word/document.xml` -- the
      python-docx `Document`/`Paragraph`/`Run` API is never used to read
      or write a paragraph that carries -- or will carry -- w:ins/w:del.
      Reuses the unzip -> lxml -> repack pattern from
      src/scripts/lib/footnote_adder.py:82-239.

  (b) Diffing is word-level per paragraph via `difflib.SequenceMatcher` on
      a token stream that keeps word and whitespace tokens as separate
      elements (`\\S+|\\s+`). Inserted/deleted tokens inside one `replace`
      opcode are treated as one positional edit group (del block emitted,
      then the paired ins block, in document order) -- there is no
      "the inserted span inherits the first run's rPr" rule (both
      docx-cli's `inheritedRprForInsert()` and docx-trackdiff moved away
      from that). An inserted run's formatting is taken from the NEAREST
      KEPT (surviving `equal`-opcode) run to its left, falling back to the
      deleted run's own formatting when the insertion is paired with a
      deletion in the same `replace` group, and only falling back to the
      paragraph's first run when an insertion occurs before any kept text
      at all.

  (c) Every new `w:id` (revisions and comments alike) is allocated as
      `max(existing w:id anywhere in word/document.xml) + 1`, monotonically
      increasing -- never reusing or guessing a range -- because the target
      `.docx` may already carry hand-built revisions from a previous
      session and colliding ids corrupt the file.

  (d) Author name is looked up per change from its `stage` field:
      "editorial" -> "Editor (Claude)", "language" -> "Language editor
      (Claude)", "mechanical" -> "Proofreader (Claude)".

  (e) Comments, never tracked edits, are used for: every `stage:
      "editorial"` finding, and every `stage: "language"` change whose
      `meaningRisk` is "medium" or "high". Comments are a REAL
      `word/comments.xml` part with `w:commentRangeStart`/
      `w:commentRangeEnd`/`w:commentReference`, wired into
      `[Content_Types].xml` (an `Override` for the comments part) and
      `word/_rels/document.xml.rels` (a `comments` relationship) -- never
      an inline "[הערה: ...]" text fallback.

  (f) Both sides of every text comparison are NFC-normalized before
      matching. This script never falls back to replacing a whole
      paragraph or the whole file: a change that cannot be located leaves
      the document exactly as it would be without that change (recorded in
      the `skipped` list of the return value/CLI output, never silently
      dropped and never patched in via a wider search).

Scope this script does NOT claim to cover (documented, not silently
skipped): a paragraph that already carries `w:ins`/`w:del` (hand-built
revisions from a prior session) is never re-diffed or otherwise touched --
requirement (a) says existing revisions must not be corrupted, and the
safest way to guarantee that is to leave such paragraphs alone entirely.
Likewise, a comment's `before` text must be located within a SINGLE plain
(non-`w:ins`/`w:del`) run's text to be placed; if it is not found there (or
spans a run boundary), it is reported skipped with reason "no-match" rather
than guessed at across boundaries or paragraphs.

Usage:
    python3 build-tracked-docx.py --original original.docx \\
        --final-text final.txt --changes changes.json \\
        --output original.proofed.docx

--original     Path to the ORIGINAL .docx (never modified in place).
--final-text   Path to a UTF-8 text file with the final corrected text,
               one paragraph per line, in the same order as the visible
               paragraphs of --original. Use "-" to read from stdin.
--changes      Path to a JSON file matching changes-schema.json: either the
               full object ({"stage": ..., "changes": [...]}) or a bare
               array of change objects, already annotated by
               apply-changes.py / citation-guard.py (i.e. carrying
               `applied` and, where relevant, `skipReason`).
--output       Path to write the `.proofed.docx` to. Not written at all
               (VER-08: no partial/empty artifact) when the changes list is
               empty -- this is reported as a clean pass, not an error.

Always prints a JSON report to stdout and exits 0, unless --original or
--changes cannot be read/parsed (exit 2, usage/IO error). No third-party
dependency beyond lxml (already a project dependency via footnote_adder.py
and generate-docx.py).
"""

from __future__ import annotations

import argparse
import copy
import datetime
import json
import os
import re
import shutil
import sys
import tempfile
import unicodedata
import zipfile
from difflib import SequenceMatcher
from pathlib import Path
from typing import Optional

from lxml import etree

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
CT_NS = "http://schemas.openxmlformats.org/package/2006/content-types"
REL_NS = "http://schemas.openxmlformats.org/package/2006/relationships"
XML_SPACE = "{http://www.w3.org/XML/1998/namespace}space"

STAGE_AUTHORS = {
    "editorial": "Editor (Claude)",
    "language": "Language editor (Claude)",
    "mechanical": "Proofreader (Claude)",
}
DEFAULT_STAGE = "mechanical"

_TOKEN_RE = re.compile(r"\S+|\s+")


def _wtag(name: str) -> str:
    return "{%s}%s" % (W_NS, name)


def _local(el) -> str:
    return etree.QName(el).localname


def _nfc(text: Optional[str]) -> Optional[str]:
    if text is None:
        return None
    return unicodedata.normalize("NFC", text)


# ---------------------------------------------------------------------------
# id allocation (finding c)
# ---------------------------------------------------------------------------


class IdAllocator:
    """Monotonic id allocator seeded at max(existing w:id) + 1."""

    def __init__(self, start: int):
        self._next = start

    def next(self) -> int:
        value = self._next
        self._next += 1
        return value


def _max_existing_id(document_root) -> int:
    max_id = 0
    id_attr = _wtag("id")
    for el in document_root.iter():
        val = el.get(id_attr)
        if val is None:
            continue
        try:
            max_id = max(max_id, int(val))
        except ValueError:
            continue
    return max_id


# ---------------------------------------------------------------------------
# paragraph text extraction / tokenization (findings a, b, f)
# ---------------------------------------------------------------------------


def _is_in_del(node) -> bool:
    parent = node.getparent()
    while parent is not None:
        if _local(parent) == "del":
            return True
        if _local(parent) == "p":
            return False
        parent = parent.getparent()
    return False


def _paragraph_text(p_el) -> str:
    """Visible text of a paragraph: every w:t not nested inside a w:del."""
    parts = []
    for t in p_el.iter(_wtag("t")):
        if _is_in_del(t):
            continue
        parts.append(t.text or "")
    return _nfc("".join(parts)) or ""


def _direct_runs(p_el):
    """Direct w:r children of a paragraph (not runs nested inside a
    pre-existing w:ins/w:del wrapper)."""
    return [c for c in p_el if _local(c) == "r"]


def _has_revision_children(p_el) -> bool:
    return any(_local(c) in ("ins", "del") for c in p_el)


def _rpr_of(run_el):
    rpr = run_el.find(_wtag("rPr"))
    return copy.deepcopy(rpr) if rpr is not None else None


def _tokenize_paragraph_with_rpr(p_el):
    """Return [(token_text, rpr_or_None), ...] for a paragraph's direct
    runs, NFC-normalized, tokenized into word/whitespace tokens kept
    separate (finding b, f)."""
    tokens = []
    for r in _direct_runs(p_el):
        rpr = r.find(_wtag("rPr"))
        text = "".join(t.text or "" for t in r.findall(_wtag("t")))
        text = _nfc(text) or ""
        for tok in _TOKEN_RE.findall(text):
            tokens.append((tok, rpr))
    return tokens


# ---------------------------------------------------------------------------
# run/ins/del construction
# ---------------------------------------------------------------------------


def _make_run(rpr_el, text: str):
    r = etree.Element(_wtag("r"))
    if rpr_el is not None:
        r.append(copy.deepcopy(rpr_el))
    t = etree.SubElement(r, _wtag("t"))
    t.set(XML_SPACE, "preserve")
    t.text = text
    return r


def _make_del_run(rpr_el, text: str):
    r = etree.Element(_wtag("r"))
    if rpr_el is not None:
        r.append(copy.deepcopy(rpr_el))
    t = etree.SubElement(r, _wtag("delText"))
    t.set(XML_SPACE, "preserve")
    t.text = text
    return r


def _make_ins(id_alloc: IdAllocator, author: str, date_str: str, run_el):
    ins = etree.Element(_wtag("ins"))
    ins.set(_wtag("id"), str(id_alloc.next()))
    ins.set(_wtag("author"), author)
    ins.set(_wtag("date"), date_str)
    ins.append(run_el)
    return ins


def _make_del(id_alloc: IdAllocator, author: str, date_str: str, run_el):
    d = etree.Element(_wtag("del"))
    d.set(_wtag("id"), str(id_alloc.next()))
    d.set(_wtag("author"), author)
    d.set(_wtag("date"), date_str)
    d.append(run_el)
    return d


# ---------------------------------------------------------------------------
# per-paragraph diff + rebuild (finding b)
# ---------------------------------------------------------------------------


def _find_attribution(applied_changes, consumed, deleted_text: str, inserted_text: str) -> str:
    """Match a diff hunk to the change that produced it, by NFC-normalized
    before/after text. Returns the stage, defaulting to 'mechanical' when no
    change matches (e.g. a hunk with no corresponding entry in the
    attribution map)."""
    deleted_norm = (deleted_text or "").strip()
    inserted_norm = (inserted_text or "").strip()
    for idx, change in enumerate(applied_changes):
        if idx in consumed:
            continue
        before = (_nfc(change.get("before")) or "").strip()
        after = _nfc(change.get("after"))
        after = after.strip() if after is not None else ""
        if before == deleted_norm and after == inserted_norm:
            consumed.add(idx)
            return change.get("stage", DEFAULT_STAGE)
    return DEFAULT_STAGE


def _rebuild_paragraph(p_el, orig_tokens_with_rpr, final_tokens, applied_changes, consumed, id_alloc, date_str, counts):
    orig_tokens = [tok for tok, _ in orig_tokens_with_rpr]
    matcher = SequenceMatcher(None, orig_tokens, final_tokens, autojunk=False)
    opcodes = matcher.get_opcodes()

    new_children = []
    # Nearest-KEPT-neighbour fallback formatting for insertions that occur
    # before any surviving text at all: default to the paragraph's first
    # original run.
    last_kept_rpr = orig_tokens_with_rpr[0][1] if orig_tokens_with_rpr else None

    for tag, i1, i2, j1, j2 in opcodes:
        if tag == "equal":
            for k in range(i1, i2):
                text, rpr = orig_tokens_with_rpr[k]
                new_children.append(_make_run(rpr, text))
                last_kept_rpr = rpr
        elif tag == "delete":
            deleted_text = "".join(orig_tokens[i1:i2])
            stage = _find_attribution(applied_changes, consumed, deleted_text, "")
            author = STAGE_AUTHORS.get(stage, STAGE_AUTHORS[DEFAULT_STAGE])
            del_rpr = orig_tokens_with_rpr[i1][1]
            new_children.append(_make_del(id_alloc, author, date_str, _make_del_run(del_rpr, deleted_text)))
            counts["del"] += 1
        elif tag == "insert":
            inserted_text = "".join(final_tokens[j1:j2])
            stage = _find_attribution(applied_changes, consumed, "", inserted_text)
            author = STAGE_AUTHORS.get(stage, STAGE_AUTHORS[DEFAULT_STAGE])
            new_children.append(_make_ins(id_alloc, author, date_str, _make_run(last_kept_rpr, inserted_text)))
            counts["ins"] += 1
        elif tag == "replace":
            deleted_text = "".join(orig_tokens[i1:i2])
            inserted_text = "".join(final_tokens[j1:j2])
            stage = _find_attribution(applied_changes, consumed, deleted_text, inserted_text)
            author = STAGE_AUTHORS.get(stage, STAGE_AUTHORS[DEFAULT_STAGE])
            del_rpr = orig_tokens_with_rpr[i1][1]
            new_children.append(_make_del(id_alloc, author, date_str, _make_del_run(del_rpr, deleted_text)))
            counts["del"] += 1
            # Nearest-kept-neighbour fallback: the inserted span takes the
            # formatting of the token it is positionally paired with (the
            # deleted run right next to it), not "the first run in the
            # paragraph".
            ins_rpr = del_rpr if del_rpr is not None else last_kept_rpr
            new_children.append(_make_ins(id_alloc, author, date_str, _make_run(ins_rpr, inserted_text)))
            counts["ins"] += 1
            last_kept_rpr = ins_rpr

    for old_r in _direct_runs(p_el):
        p_el.remove(old_r)
    for node in new_children:
        p_el.append(node)


# ---------------------------------------------------------------------------
# comments (findings e, f)
# ---------------------------------------------------------------------------


def _is_comment_worthy(change: dict) -> bool:
    if change.get("stage") == "editorial":
        return True
    if change.get("stage") == "language" and change.get("meaningRisk") in ("medium", "high"):
        return True
    return False


def _try_insert_comment(p_el, before_text: str, change: dict, id_alloc: IdAllocator, date_str: str, comment_entries: list) -> bool:
    """Locate `before_text` inside a single plain run of `p_el` and wrap it
    with commentRangeStart/commentRangeEnd + a commentReference run. Returns
    True on success. Never touches runs nested inside w:ins/w:del."""
    for r in _direct_runs(p_el):
        t_el = r.find(_wtag("t"))
        if t_el is None or not t_el.text:
            continue
        text = t_el.text
        text_norm = _nfc(text) or ""
        idx = text_norm.find(before_text)
        if idx == -1:
            continue

        comment_id = id_alloc.next()
        author = STAGE_AUTHORS.get(change.get("stage"), STAGE_AUTHORS[DEFAULT_STAGE])
        comment_entries.append((comment_id, author, date_str, change.get("rationale") or ""))

        before_part = text[:idx]
        match_part = text[idx : idx + len(before_text)]
        after_part = text[idx + len(before_text) :]
        rpr = _rpr_of(r)

        new_nodes = []
        range_start = etree.Element(_wtag("commentRangeStart"))
        range_start.set(_wtag("id"), str(comment_id))
        new_nodes.append(range_start)

        if before_part:
            new_nodes.append(_make_run(rpr, before_part))
        new_nodes.append(_make_run(rpr, match_part))

        range_end = etree.Element(_wtag("commentRangeEnd"))
        range_end.set(_wtag("id"), str(comment_id))
        new_nodes.append(range_end)

        ref_run = etree.Element(_wtag("r"))
        ref_rpr = etree.SubElement(ref_run, _wtag("rPr"))
        ref_style = etree.SubElement(ref_rpr, _wtag("rStyle"))
        ref_style.set(_wtag("val"), "CommentReference")
        ref = etree.SubElement(ref_run, _wtag("commentReference"))
        ref.set(_wtag("id"), str(comment_id))
        new_nodes.append(ref_run)

        if after_part:
            new_nodes.append(_make_run(rpr, after_part))

        parent = r.getparent()
        insert_pos = list(parent).index(r)
        parent.remove(r)
        for offset, node in enumerate(new_nodes):
            parent.insert(insert_pos + offset, node)
        return True
    return False


def _write_comments_part(extract_dir: str, comment_entries: list) -> None:
    comments_path = os.path.join(extract_dir, "word", "comments.xml")
    root = etree.Element(_wtag("comments"), nsmap={"w": W_NS})
    for cid, author, date_str, text in comment_entries:
        c = etree.SubElement(root, _wtag("comment"))
        c.set(_wtag("id"), str(cid))
        c.set(_wtag("author"), author)
        c.set(_wtag("date"), date_str)
        initials = "".join(part[0] for part in author.split() if part and part[0].isalpha())[:3] or "AC"
        c.set(_wtag("initials"), initials)
        p = etree.SubElement(c, _wtag("p"))
        r = etree.SubElement(p, _wtag("r"))
        t = etree.SubElement(r, _wtag("t"))
        t.set(XML_SPACE, "preserve")
        t.text = text
    etree.ElementTree(root).write(comments_path, xml_declaration=True, encoding="UTF-8", standalone=True)


def _wire_comments_part(extract_dir: str) -> None:
    ct_path = os.path.join(extract_dir, "[Content_Types].xml")
    ct_tree = etree.parse(ct_path)
    ct_root = ct_tree.getroot()
    already_wired = any(
        _local(el) == "Override" and el.get("PartName") == "/word/comments.xml" for el in ct_root
    )
    if not already_wired:
        override = etree.SubElement(ct_root, "{%s}Override" % CT_NS)
        override.set("PartName", "/word/comments.xml")
        override.set(
            "ContentType",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml",
        )
        ct_tree.write(ct_path, xml_declaration=True, encoding="UTF-8", standalone=True)

    rels_path = os.path.join(extract_dir, "word", "_rels", "document.xml.rels")
    rels_tree = etree.parse(rels_path)
    rels_root = rels_tree.getroot()
    already_related = any(
        el.get("Target") == "comments.xml" for el in rels_root if _local(el) == "Relationship"
    )
    if already_related:
        return

    max_num = 0
    for el in rels_root:
        rid = el.get("Id", "")
        m = re.match(r"rId(\d+)$", rid)
        if m:
            max_num = max(max_num, int(m.group(1)))
    rel = etree.SubElement(rels_root, "{%s}Relationship" % REL_NS)
    rel.set("Id", "rId%d" % (max_num + 1))
    rel.set(
        "Type",
        "http://schemas.openxmlformats.org/officeDocument/2006/relationships/comments",
    )
    rel.set("Target", "comments.xml")
    rels_tree.write(rels_path, xml_declaration=True, encoding="UTF-8", standalone=True)


# ---------------------------------------------------------------------------
# repack (reuses the priority-order pattern from footnote_adder.py:82-239)
# ---------------------------------------------------------------------------


def _repack_docx(extract_dir: str, output_path: str) -> None:
    all_files = []
    for root_dir, _dirs, files in os.walk(extract_dir):
        for file in files:
            file_path = os.path.join(root_dir, file)
            arcname = os.path.relpath(file_path, extract_dir).replace(os.sep, "/")
            all_files.append((file_path, arcname))

    priority_order = [
        "[Content_Types].xml",
        "_rels/.rels",
        "word/_rels/document.xml.rels",
        "word/document.xml",
        "word/comments.xml",
        "word/footnotes.xml",
        "word/endnotes.xml",
    ]

    def sort_key(item):
        try:
            return (priority_order.index(item[1]), item[1])
        except ValueError:
            return (len(priority_order), item[1])

    all_files.sort(key=sort_key)

    tmp_output = output_path + ".tmp"
    with zipfile.ZipFile(tmp_output, "w", zipfile.ZIP_DEFLATED) as zf:
        for file_path, arcname in all_files:
            zf.write(file_path, arcname)
    os.replace(tmp_output, output_path)


# ---------------------------------------------------------------------------
# main entry point
# ---------------------------------------------------------------------------


def build_tracked_docx(original_path: str, final_text: str, changes_payload, output_path: str) -> dict:
    """Build `output_path` as a tracked-changes/commented copy of
    `original_path`. Returns a JSON-serializable report:
    {"written": bool, "output_path": str|None, "reason": str|None,
     "counts": {"ins": int, "del": int, "comment": int},
     "skipped": [{"change": <change dict>, "reason": str}, ...]}
    """
    if isinstance(changes_payload, dict):
        changes = list(changes_payload.get("changes", []))
    elif isinstance(changes_payload, list):
        changes = list(changes_payload)
    else:
        raise ValueError("changes payload must be a JSON object or array")

    counts = {"ins": 0, "del": 0, "comment": 0}

    # VER-08: an empty change list produces no .proofed.docx at all and
    # reports a clean pass -- not an error, not an empty artifact.
    if not changes:
        return {
            "written": False,
            "output_path": None,
            "reason": "no-changes",
            "counts": counts,
            "skipped": [],
        }

    extract_dir = tempfile.mkdtemp()
    skipped: list[dict] = []
    try:
        with zipfile.ZipFile(original_path, "r") as zf:
            zf.extractall(extract_dir)

        doc_path = os.path.join(extract_dir, "word", "document.xml")
        tree = etree.parse(doc_path)
        root = tree.getroot()
        body = root.find(_wtag("body"))
        paragraphs = body.findall(_wtag("p"))

        id_alloc = IdAllocator(_max_existing_id(root) + 1)
        date_str = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

        final_text_norm = _nfc(final_text) or ""
        final_paragraphs = final_text_norm.split("\n")

        applied_changes = [c for c in changes if c.get("applied") is True and c.get("after") is not None]
        consumed: set[int] = set()

        for idx, p_el in enumerate(paragraphs):
            if _has_revision_children(p_el):
                # Finding (a): never touch a paragraph that already carries
                # hand-built revisions from a previous session.
                continue

            orig_text = _paragraph_text(p_el)
            final_para_text = final_paragraphs[idx] if idx < len(final_paragraphs) else orig_text
            final_para_text = _nfc(final_para_text) or ""
            if orig_text == final_para_text:
                continue

            tokens_with_rpr = _tokenize_paragraph_with_rpr(p_el)
            final_tokens = _TOKEN_RE.findall(final_para_text)
            _rebuild_paragraph(p_el, tokens_with_rpr, final_tokens, applied_changes, consumed, id_alloc, date_str, counts)

        for idx, change in enumerate(applied_changes):
            if idx not in consumed:
                skipped.append({"change": change, "reason": "no-match"})

        comment_changes = [c for c in changes if _is_comment_worthy(c)]
        comment_entries: list = []
        for change in comment_changes:
            before = _nfc(change.get("before"))
            if not before:
                skipped.append({"change": change, "reason": "no-match"})
                continue
            placed = False
            for p_el in paragraphs:
                if _has_revision_children(p_el):
                    continue
                if _try_insert_comment(p_el, before, change, id_alloc, date_str, comment_entries):
                    placed = True
                    counts["comment"] += 1
                    break
            if not placed:
                skipped.append({"change": change, "reason": "no-match"})

        if comment_entries:
            _write_comments_part(extract_dir, comment_entries)
            _wire_comments_part(extract_dir)

        tree.write(doc_path, xml_declaration=True, encoding="UTF-8", standalone=True)

        _repack_docx(extract_dir, output_path)
    finally:
        shutil.rmtree(extract_dir, ignore_errors=True)

    return {
        "written": True,
        "output_path": output_path,
        "reason": None,
        "counts": counts,
        "skipped": skipped,
    }


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Build a .proofed.docx with real Word tracked changes and comments."
    )
    parser.add_argument("--original", required=True, help="Path to the original .docx.")
    parser.add_argument(
        "--final-text",
        required=True,
        help="Path to a UTF-8 text file with the final corrected text (one paragraph per line), or '-' for stdin.",
    )
    parser.add_argument(
        "--changes",
        required=True,
        help="Path to a JSON file matching changes-schema.json (object or bare array).",
    )
    parser.add_argument("--output", required=True, help="Path to write the .proofed.docx to.")
    return parser


def main(argv: Optional[list[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)

    try:
        if args.final_text == "-":
            final_text = sys.stdin.read()
        else:
            final_text = Path(args.final_text).read_text(encoding="utf-8")
        changes_payload = json.loads(Path(args.changes).read_text(encoding="utf-8"))
    except OSError as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 2
    except json.JSONDecodeError as exc:
        print(json.dumps({"error": f"invalid JSON in --changes: {exc}"}), file=sys.stderr)
        return 2

    try:
        result = build_tracked_docx(args.original, final_text, changes_payload, args.output)
    except (OSError, ValueError, KeyError) as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 2

    print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())
